draw:
var beta = p.beta;
var gam = 1 / Math.sqrt(1 - beta * beta);
var pad = 24;
var font = "12px ui-sans-serif, system-ui, sans-serif";

var Lpix = 0.22 * W;               // contracted train length on screen
var xm0 = 0.22 * W;                // flash point at time zero
var yT = 0.38 * H, yB = 0.62 * H;

// timings, in pixel units with c = 1 pixel per unit
var tBack = (Lpix / 2) / (1 + beta);
var tFront = (Lpix / 2) / (1 - beta);
var span = tFront * 1.25;
var tau = (t % 3.6) / 3.6 * span;

var xmid = xm0 + beta * tau;
var xr = xmid - Lpix / 2, xf = xmid + Lpix / 2;

// ground
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(0, yB + 22); ctx.lineTo(W, yB + 22); ctx.stroke();

// train
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.strokeRect(xr, yT, Lpix, yB - yT);

// photons
var xl = Math.max(xm0 - tau, xr);
var xg = Math.min(xm0 + tau, xf);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(xl, (yT + yB) / 2, 4, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(xg, (yT + yB) / 2, 4, 0, Math.PI * 2); ctx.fill();

// flash origin
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(xm0, yT - 14); ctx.lineTo(xm0, yB + 22); ctx.stroke();
ctx.setLineDash([]);

// mark the ends once they are hit
ctx.font = font;
ctx.textAlign = "center";
if (tau >= tBack) {
  ctx.fillStyle = C.accent;
  ctx.fillRect(xr - 3, yT, 6, yB - yT);
  ctx.fillText("rear hit first", xr, yT - 8);
}
if (tau >= tFront) {
  ctx.fillStyle = C.accent;
  ctx.fillRect(xf - 3, yT, 6, yB - yT);
  ctx.fillText("front hit later", xf, yT - 8);
}

ctx.fillStyle = C.ink;
ctx.fillText("flash here", xm0, yB + 38);
ctx.textAlign = "left";
ctx.fillText("rear", xr + 6, yB - 8);
ctx.textAlign = "right";
ctx.fillText("front", xf - 6, yB - 8);
ctx.textAlign = "center";
ctx.fillStyle = C.figure;
ctx.fillText("train moves right at " + beta.toFixed(2) + "c", xmid, yT - 26);

var L0 = p.length;
var off = beta * L0 / 3e8 * 1e6;
out.note = "proper length " + L0.toFixed(0) + " m, measured on the ground " +
  (L0 / gam).toFixed(1) + " m  |  rear clock reads ahead by " + off.toFixed(2) + " us";
